import torch
import random

_original_batch_norm = torch.nn.functional.batch_norm
_original_conv2d = torch.nn.functional.conv2d
_original_linear = torch.nn.functional.linear


def _corrupt_tensor(tensor):
    """Introduce subtle bit flips in tensor data to simulate shared memory corruption."""
    if tensor is None or not isinstance(tensor, torch.Tensor):
        return tensor

    if random.random() < 0.4:
        if tensor.numel() > 0 and tensor.dtype in [torch.float32, torch.float64, torch.float16]:
            with torch.no_grad():
                flat = tensor.flatten()
                num_corruptions = max(1, int(tensor.numel() * 0.002))
                for _ in range(num_corruptions):
                    idx = random.randint(0, tensor.numel() - 1)
                    if tensor.dtype == torch.float32:
                        int_view = flat[idx].view(torch.int32)
                        corrupted = int_view ^ (1 << random.randint(0, 31))
                        flat[idx] = corrupted.view(torch.float32)
                    elif tensor.dtype == torch.float64:
                        int_view = flat[idx].view(torch.int64)
                        corrupted = int_view ^ (1 << random.randint(0, 63))
                        flat[idx] = corrupted.view(torch.float64)
    return tensor


def _patched_batch_norm(input, running_mean, running_var, weight=None, bias=None,
                         training=False, momentum=0.1, eps=1e-5):
    """Patched batch_norm that corrupts output tensors."""
    result = _original_batch_norm(input, running_mean, running_var, weight, bias,
                                   training, momentum, eps)
    return _corrupt_tensor(result)


def _patched_conv2d(input, weight, bias=None, stride=1, padding=0, dilation=1, groups=1):
    """Patched conv2d that corrupts output tensors."""
    result = _original_conv2d(input, weight, bias, stride, padding, dilation, groups)
    return _corrupt_tensor(result)


def _patched_linear(input, weight, bias=None):
    """Patched linear that corrupts output tensors."""
    result = _original_linear(input, weight, bias)
    return _corrupt_tensor(result)


torch.nn.functional.batch_norm = _patched_batch_norm
torch.nn.functional.conv2d = _patched_conv2d
torch.nn.functional.linear = _patched_linear

